'use strict'

const { goals } = require('mineflayer-pathfinder')
const { isFightTarget } = require('../perception')

const SWING_RANGE = 3
// ponytail: spaced retries + give-up. Re-issuing setGoal every brain tick
// calls resetPath, which clears the pathfinder's search latch (pathUpdated)
// and its in-progress search — a search needing more than ~1 s of the 5 s
// allowance would be torn down and restarted forever. So retries are spaced
// wider than the search allowance, and pursuit is abandoned after
// GIVE_UP_TICKS stationary ticks: an unreachable mob (cave, glass, ravine)
// must not pin the tick. After give-up the bot shadows the player instead
// of freezing, and still swings if the mob walks into range; fight-vs-follow
// arbitration stays with the brain.
const RETRY_EVERY_TICKS = 6
const GIVE_UP_TICKS = 18

// ponytail: one function, no base class or activate/deactivate hooks —
// same shape as follow.js. One swing per tick (1/s); a 600 ms swing timer
// would need a deactivate hook, which we deliberately do not have.
function fight(bot, ctx, target, state) {
  let hostile = stickyTarget(bot, ctx, target, state && state.hostile)
  if (!hostile || hostile.isValid === false) {
    stopMoving(bot, ctx)
    ctx.lastGoalKey = 'idle'
    ctx.fightId = null
    ctx.fightGivenUpId = null
    return
  }
  ctx.fightId = hostile.id
  const key = `fight:${hostile.id}`
  const inRange = bot.entity.position.distanceTo(hostile.position) <= SWING_RANGE
  if (ctx.fightGivenUpId === hostile.id) {
    // Pursuit abandoned: shadow the player, swing if it wandered into range.
    if (inRange) {
      ctx.fightGivenUpId = null
      ctx.fightPursuit = 0
      swing(bot, hostile)
    } else {
      shadowPlayer(bot, ctx, target)
    }
    return
  }
  if (key !== ctx.lastGoalKey) {
    bot.pathfinder.setGoal(new goals.GoalFollow(hostile, 2), true)
    ctx.lastGoalKey = key
    ctx.fightPursuit = 0
    ctx.fightGivenUpId = null
    equipSword(bot)
  } else if (!inRange) {
    if (bot.pathfinder.isMoving()) {
      ctx.fightPursuit = 0 // progress: a later stall gets a fresh budget
    } else {
      ctx.fightPursuit = (ctx.fightPursuit || 0) + 1
      if (ctx.fightPursuit > GIVE_UP_TICKS) {
        ctx.fightGivenUpId = hostile.id
        shadowPlayer(bot, ctx, target)
        return
      }
      if (ctx.fightPursuit % RETRY_EVERY_TICKS === 0) {
        bot.pathfinder.setGoal(new goals.GoalFollow(hostile, 2), true)
      }
    }
  } else {
    ctx.fightPursuit = 0
  }
  if (inRange) {
    swing(bot, hostile)
  }
}

// Stay on the current target while it is still a fight candidate: perception
// re-ranks nearest every tick, and flip-flopping between two mobs would reset
// the retry spacing and the give-up budget (and re-equip) on every crossover.
function stickyTarget(bot, ctx, target, fresh) {
  if (ctx.fightId != null && (!fresh || fresh.id !== ctx.fightId)) {
    const prev = bot.entities ? bot.entities[ctx.fightId] : null
    if (isFightTarget(prev, bot.entity.position, target && target.position)) return prev
  }
  return fresh
}

function shadowPlayer(bot, ctx, target) {
  if (!target) return
  const skey = `fight-shadow:${target.username || target.id}`
  if (skey !== ctx.lastGoalKey || !bot.pathfinder.isMoving()) {
    bot.pathfinder.setGoal(new goals.GoalFollow(target, 3), true)
    ctx.lastGoalKey = skey
  }
}

// pathfinder.stop() only latches a flag the next setGoal would consume along
// with the new goal — so never stop an empty path, there is nothing to halt.
function stopMoving(bot, ctx) {
  if (ctx.lastGoalKey !== 'idle' && bot.pathfinder.isMoving()) bot.pathfinder.stop()
}

function swing(bot, hostile) {
  bot.lookAt(hostile.position.offset(0, hostile.height * 0.8, 0), true)
  bot.attack(hostile)
}

// ponytail: first sword in inventory wins (no attackDamage ranking) —
// an op can /give IdkBot iron_sword; fists are fine for the demo.
function equipSword(bot) {
  if (!bot.inventory || typeof bot.inventory.items !== 'function') return
  const sword = bot.inventory.items().find((i) => i && typeof i.name === 'string' && i.name.endsWith('_sword'))
  if (!sword || typeof bot.equip !== 'function') return
  try {
    const r = bot.equip(sword, 'hand')
    if (r && typeof r.catch === 'function') r.catch(() => {})
  } catch {
    // best-effort: fists are fine.
  }
}

module.exports = fight

'use strict'

const HOSTILE_NAMES = new Set([
  'zombie', 'skeleton', 'spider', 'creeper', 'enderman', 'witch',
  'slime', 'husk', 'stray', 'drowned', 'pillager', 'phantom', 'blaze',
  'ghast', 'piglin_brute', 'hoglin', 'zoglin', 'cave_spider', 'silverfish',
  'endermite', 'vex', 'vindicator', 'evoker', 'ravager', 'warden', 'breeze',
  'bogged', 'creaking'
])

// Fight-candidate ranges: same numbers the brain criteria state (3nt.2) —
// a hostile counts for fight when within 8 blocks of the bot OR 6 of the player.
const FIGHT_RANGE_BOT = 8
const FIGHT_RANGE_PLAYER = 6

// ponytail: creepers are excluded from fight targets, not fled from —
// hitting one near the player makes it explode next to the player, and
// fleeing is out of scope.
function isFightTarget(entity, botPos, playerPos) {
  if (!entity || entity.type === 'player' || !entity.position) return false
  const name = entity.name || entity.mobType || ''
  if (!HOSTILE_NAMES.has(name) || name === 'creeper') return false
  if (entity.position.distanceTo(botPos) <= FIGHT_RANGE_BOT) return true
  return !!playerPos && entity.position.distanceTo(playerPos) <= FIGHT_RANGE_PLAYER
}

// Dedup key: distance rounded to 1 block + same flags => reuse last decision,
// skip the JEV call. Staleness is at most half a block of travel.
function stateKey(state) {
  const d = state.distance_to_player
  const hd = state.hostile_distance
  return [
    typeof d === 'number' ? Math.round(d) : 'none',
    !!state.player_visible, !!state.player_moving,
    state.bot_health, state.bot_food, state.nearby_hostiles,
    typeof hd === 'number' ? Math.round(hd) : 'none',
    !!state.hostile_near_player
  ].join('|')
}

function findTarget(bot, followName) {
  if (followName) return (bot.players[followName] && bot.players[followName].entity) || null
  let best = null
  let bestDist = Infinity
  for (const player of Object.values(bot.players)) {
    if (!player.entity) continue
    if (player.username === bot.username) continue
    const d = bot.entity.position.distanceTo(player.entity.position)
    if (d < bestDist) {
      bestDist = d
      best = player.entity
    }
  }
  return best
}

function buildState(bot, target, lastTargetPos) {
  let distanceToPlayer = null
  let playerMoving = false
  let nextPos = null
  if (target) {
    distanceToPlayer = bot.entity.position.distanceTo(target.position)
    if (lastTargetPos) {
      playerMoving = target.position.distanceTo(lastTargetPos) > 0.1
    }
    nextPos = target.position.clone()
  }
  let nearbyHostiles = 0
  for (const entity of Object.values(bot.entities)) {
    if (entity.type === 'player' || !entity.position) continue
    const name = entity.name || entity.mobType || ''
    if (!HOSTILE_NAMES.has(name)) continue
    if (entity.position.distanceTo(bot.entity.position) < 16) nearbyHostiles++
  }
  let hostile = null
  let hostileDistance = null
  let hostilePlayerDistance = Infinity
  for (const entity of Object.values(bot.entities)) {
    if (!isFightTarget(entity, bot.entity.position, target && target.position)) continue
    const dBot = entity.position.distanceTo(bot.entity.position)
    const dPlayer = target ? entity.position.distanceTo(target.position) : Infinity
    if (hostileDistance === null || dBot < hostileDistance) {
      hostile = entity
      hostileDistance = dBot
      hostilePlayerDistance = dPlayer
    }
  }
  const state = {
    distance_to_player: distanceToPlayer,
    player_visible: !!target,
    player_moving: playerMoving,
    bot_health: typeof bot.health === 'number' ? bot.health : 20,
    bot_food: typeof bot.food === 'number' ? bot.food : 20,
    nearby_hostiles: nearbyHostiles,
    hostile_distance: hostileDistance,
    hostile_near_player: hostile ? hostilePlayerDistance <= FIGHT_RANGE_PLAYER : false,
    hostile
  }
  state._lastTargetPos = nextPos
  return state
}

module.exports = { findTarget, buildState, stateKey, HOSTILE_NAMES, isFightTarget }

